import { useState } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { usePeople } from '../people/people';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { claimsKey, useClaims } from './claims';
import type { Claim } from './claims';
import { useSelectedClaims } from './selection';
import { useOneAtATime } from '../../query/useOneAtATime';

// Opens every ticked claim, one after another in list order (people in their order, each one's
// claims newest first), so they are numbered in that order. Each goes through the claim's own open
// action: one the server refuses is left as it is and counted as refused.
export function BulkOpen() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const people = usePeople().data ?? [];
  const claims = useClaims().data ?? [];
  const [selected, , clear] = useSelectedClaims();
  const [result, setResult] = useState<{ opened: number; refused: number } | undefined>(undefined);
  const [busy, setBusy] = useState(false);
  const queryClient = useQueryClient();
  const once = useOneAtATime();

  if (!user || !sheet) return null;

  const run = async () => {
    setResult(undefined);
    setBusy(true);
    const ordered = people.flatMap((p) => claims.filter((c) => c.personId === p.id && selected.has(c.id)));
    let opened = 0;
    let refused = 0;
    try {
      for (const c of ordered) {
        try {
          await postJson<Claim>(
            `/api/sheets/${encodeURIComponent(sheet)}/claims/${c.id}/open?user=${encodeURIComponent(user)}`,
            {},
          );
          opened++;
        } catch {
          refused++;
        }
      }
      // A ticked claim no longer listed (gone from the sheet) cannot be opened.
      refused += selected.size - ordered.length;
      clear();
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
    } finally {
      setBusy(false);
      setResult({ opened, refused });
    }
  };

  return (
    <p>
      <button type="button" data-testid="bulk-open" disabled={busy} onClick={() => once(run)}>
        Open selected claims
      </button>
      {result && (
        <>
          {' '}
          Opened <span data-testid="bulk-opened">{result.opened}</span>, refused{' '}
          <span data-testid="bulk-refused">{result.refused}</span>
        </>
      )}
    </p>
  );
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { bound, deferred, isOpen } from '../claims/claims';
import type { Claim, ClaimStatus } from '../claims/claims';
import { covers, liveHolds } from '../people/people';
import type { Person } from '../people/people';
import { claimDue, total } from '../rates/rates';
import type { Rate } from '../rates/rates';
import { sheetKey, useCurrentSheet } from '../session/session';
import type { DueRules } from '../settings/settings';

/**
 * A period as the store holds it: its name (unique on the sheet), its from and to dates (yyyy-MM-dd),
 * both inclusive, whether it is closed and, when closed, the due-total fixed then (null while open) and each
 * person's due-total fixed then, by person id (empty while open). A soft-closed period (soft; never also closed)
 * keeps its figures fixed the same way, while claims dated in it can still be added and changed.
 */
export type Period = {
  name: string;
  from: string;
  to: string;
  closed: boolean;
  closedTotal: string | null;
  personTotals: Record<string, string>;
  soft: boolean;
};

/** The fields the period form submits. */
export type PeriodInput = { name: string; from: string; to: string };

/** The query key for the sheet's periods; under sheetKey, so re-loading the sheet re-reads them. */
export const periodsKey = (sheet: string) => [...sheetKey(sheet), 'periods'] as const;

/** The sheet's periods, earliest first. */
export function usePeriods() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: periodsKey(sheet),
    queryFn: () => getJson<Period[]>(`/api/sheets/${encodeURIComponent(sheet)}/periods`),
    enabled: !!sheet,
  });
}

/**
 * The fiscal year the date (yyyy-MM-dd) falls in, FY<yyyy>: a fiscal year starts on the first of the start month (1 to 12)
 * and is named by the calendar year that first day falls in.
 */
export const fiscalYearOf = (date: string, startMonth: number) => {
  const year = Number(date.slice(0, 4));
  return `FY${Number(date.slice(5, 7)) < startMonth ? year - 1 : year}`;
};

/** Whether the date (yyyy-MM-dd) falls in the period, both ends included. */
export const contains = (p: Period, date: string) => p.from <= date && date <= p.to;

/** The period whose dates contain the date; undefined with none. Periods never overlap, so there is at most one. */
export const periodOf = (periods: Period[], date: string) => periods.find((p) => contains(p, date));

/**
 * The status a claim had at the end of the day (yyyy-MM-dd), as its status log records it: the last line logged on
 * or before it; undefined when it was added after. A claim with no log at all is taken at its status now.
 */
export function statusAt(c: Claim, date: string): ClaimStatus | undefined {
  if (c.log.length === 0) return c.status;
  let status: ClaimStatus | undefined;
  for (const line of c.log) if (line.date <= date) status = line.status;
  return status;
}

/**
 * Whether a claim counts toward a period: by the status it had at the end of the period's last day (OPEN, PENDING
 * or SETTLED then), left out as the live rules say while it is deferred, or when it was open then, is open still, one
 * of its person's `holds` covers its date and no statement binds it (a hold leaves out only open claims).
 */
export const countsInPeriod = (period: Period, c: Claim, holds: Person['holds'], today: string) => {
  const then = statusAt(c, period.to);
  if (then === 'SETTLED') return true;
  if (then !== 'OPEN' && then !== 'PENDING') return false;
  return !deferred(c, today) && (!isOpen(c) || bound(c) || !holds.some((h) => covers(h, c.date)));
};

/**
 * A person's due-total for a period: the dues (late charges included, as shown now) of their claims due by a date in it
 * that count by their status at the period's end, added up; a closed period keeps the figure fixed when it was
 * closed or soft-closed (0.00 for a person added since).
 */
export function personPeriodDue(period: Period, person: Person, claims: Claim[], rates: Rate[], rules: DueRules): string {
  if (period.closed || period.soft) return period.personTotals?.[String(person.id)] ?? '0.00';
  const figures = claims
    .filter((c) => c.personId === person.id && contains(period, c.dueBy) && countsInPeriod(period, c, liveHolds(person, rules.today), rules.today))
    .map((c) => claimDue(c, rates, person.grades, rules));
  return total(figures);
}

/** A period's due-total: the people's due-totals for it, added up. */
export function periodDue(period: Period, claims: Claim[], people: Person[], rates: Rate[], rules: DueRules): string {
  return total(people.map((p) => personPeriodDue(period, p, claims, rates, rules)));
}
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useClaims } from '../claims/claims';
import { usePeople } from '../people/people';
import { useRates } from '../rates/rates';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { useDueRules, useSettings } from '../settings/settings';
import { fiscalYearOf, periodDue, periodsKey, usePeriods } from './periods';
import type { Period, PeriodInput } from './periods';
import { useOneAtATime } from '../../query/useOneAtATime';

const EMPTY: PeriodInput = { name: '', from: '', to: '' };

/** yyyy-MM-dd. */
const DATE = /^\d{4}-\d{2}-\d{2}$/;

// The sheet's periods, each with its due-total, and the form that adds one.
export function Periods() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const periods = usePeriods().data ?? [];
  const claims = useClaims().data ?? [];
  const people = usePeople().data ?? [];
  const rates = useRates().data ?? [];
  const rules = useDueRules();
  const fiscalStartMonth = Number(useSettings().data?.fiscalStartMonth || 1);
  const [form, setForm] = useState<PeriodInput>(EMPTY);
  const [error, setError] = useState('');
  const queryClient = useQueryClient();
  const once = useOneAtATime();

  const add = useMutation({
    mutationFn: (input: PeriodInput) =>
      postJson<Period>(`/api/sheets/${encodeURIComponent(sheet)}/periods?user=${encodeURIComponent(user)}`, input),
    onSuccess: async () => {
      setForm(EMPTY);
      setError('');
      await queryClient.invalidateQueries({ queryKey: periodsKey(sheet) });
    },
    onError: () => setError('That period could not be added: its name must be new and its dates must not overlap another period.'),
  });

  // The generate form: one period per calendar month from the from-date's month to the to-date's month.
  const [gen, setGen] = useState({ from: '', to: '' });
  const [genError, setGenError] = useState('');
  const [made, setMade] = useState<number | undefined>(undefined);
  const generate = useMutation({
    mutationFn: (input: { from: string; to: string }) =>
      postJson<{ made: number }>(
        `/api/sheets/${encodeURIComponent(sheet)}/generate-periods?user=${encodeURIComponent(user)}`,
        input,
      ),
    onSuccess: async (result) => {
      await queryClient.invalidateQueries({ queryKey: periodsKey(sheet) });
      setMade(result.made);
    },
    onError: () => setGenError('No periods were generated: the to-date must not be before the from-date.'),
  });

  // The fiscal year form: the twelve monthly periods of the fiscal year typed, made as the generate form makes them.
  const [fyYear, setFyYear] = useState('');
  const generateFy = useMutation({
    mutationFn: (input: { year: string }) =>
      postJson<{ made: number }>(
        `/api/sheets/${encodeURIComponent(sheet)}/generate-fiscal-year?user=${encodeURIComponent(user)}`,
        input,
      ),
    onSuccess: async (result) => {
      await queryClient.invalidateQueries({ queryKey: periodsKey(sheet) });
      setMade(result.made);
    },
    onError: () => setGenError('No periods were generated: type the fiscal year as yyyy.'),
  });

  // The period whose close or reopen was refused, and why; cleared by the next action on a period.
  const [rowError, setRowError] = useState<{ name: string; message: string } | null>(null);
  const act = useMutation({
    mutationFn: ({ name, action }: { name: string; action: 'close' | 'soft-close' | 'reopen' }) =>
      postJson<Period>(
        `/api/sheets/${encodeURIComponent(sheet)}/periods/${encodeURIComponent(name)}/${action}?user=${encodeURIComponent(user)}`,
        {},
      ),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: periodsKey(sheet) });
    },
    onError: (_e, { name, action }) =>
      setRowError({
        name,
        message:
          action === 'close'
            ? 'That period could not be closed: it is already closed, or your role is not allowed to close a period.'
            : action === 'soft-close'
              ? 'That period could not be soft-closed: it is already closed or soft-closed, or your role is not allowed to close a period.'
              : 'That period could not be reopened: it is not closed, or your role is not allowed to reopen a period.',
      }),
  });

  if (!user || !sheet) return null;

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    const input = { name: form.name.trim(), from: form.from.trim(), to: form.to.trim() };
    if (input.name === '') {
      setError('Type a name for the period.');
      return;
    }
    if (!DATE.test(input.from) || !DATE.test(input.to)) {
      setError('Type the from and to dates as yyyy-mm-dd.');
      return;
    }
    if (input.to < input.from) {
      setError('The to-date must not be before the from-date.');
      return;
    }
    once(() => add.mutateAsync(input));
  };

  const submitGenerate = (e: FormEvent) => {
    e.preventDefault();
    setGenError('');
    setMade(undefined);
    const input = { from: gen.from.trim(), to: gen.to.trim() };
    if ((input.from && !DATE.test(input.from)) || (input.to && !DATE.test(input.to))) {
